module TopModule(
    input  in,
    input  [9:0] state,
    output [9:0] next_state,
    output out1,
    output out2
);
    wire [9:0] state0 = state[0];
    wire [9:0] state1 = state[1];
    wire [9:0] state2 = state[2];
    wire [9:0] state3 = state[3];
    wire [9:0] state4 = state[4];
    wire [9:0] state5 = state[5];
    wire [9:0] state6 = state[6];
    wire [9:0] state7 = state[7];
    wire [9:0] state8 = state[8];
    wire [9:0] state9 = state[9];
    wire [9:0] next0 = state0 & ~in | state1 & in;
    wire [9:0] next1 = state1 & ~in | state2 & in;
    wire [9:0] next2 = state2 & ~in | state3 & in;
    wire [9:0] next3 = state3 & ~in | state4 & in;
    wire [9:0] next4 = state4 & ~in | state5 & in;
    wire [9:0] next5 = state5 & ~in | state8 & ~out1 | state6 & out1;
    wire [9:0] next6 = state6 & ~in | state9 & ~out1 | state7 & out1;
    wire [9:0] next7 = state7 & ~in | state7 & out1;
    wire [9:0] next8 = state8 & ~in | state0 & ~out1 | state1 & out1;
    wire [9:0] next9 = state9 & ~in | state0 & ~out1 | state1 & out1;
    assign next_state = {next0, next1, next2, next3, next4, next5, next6, next7, next8, next9};
    assign out1 = state5 & out1 | state6 & ~out1;
    assign out2 = state8 & ~out1 | state9 & out1;
endmodule

